import { useState, useEffect } from 'react';
import './styles.css';

type AlgorithmType = 'classification' | 'regression' | 'clustering' | 'reinforcement';

interface QuizQuestion {
  description: string;
  answer: AlgorithmType;
  hint: string;
}

const quizQuestions: QuizQuestion[] = [
  { description: 'An email system that sorts messages into Spam or Not Spam', answer: 'classification', hint: 'Sorting into predefined categories' },
  { description: 'Predicting tomorrow\'s temperature based on historical weather data', answer: 'regression', hint: 'Predicting a number' },
  { description: 'Grouping customers based on shopping behavior (without predefined groups)', answer: 'clustering', hint: 'Discovering natural groups' },
  { description: 'Teaching a robot to walk by rewarding successful steps', answer: 'reinforcement', hint: 'Learning through trial and error' },
];

function ClassificationViz({ isPlaying }: { isPlaying: boolean }) {
  const blueDots = [
    { startX: 45, startY: 30, endX: 35, endY: 65 },
    { startX: 120, startY: 25, endX: 50, endY: 65 },
    { startX: 80, startY: 35, endX: 45, endY: 65 },
    { startX: 160, startY: 20, endX: 60, endY: 65 },
  ];
  const redDots = [
    { startX: 60, startY: 20, endX: 135, endY: 65 },
    { startX: 140, startY: 35, endX: 150, endY: 65 },
    { startX: 90, startY: 25, endX: 145, endY: 65 },
    { startX: 170, startY: 30, endX: 160, endY: 65 },
  ];

  return (
    <svg viewBox="0 0 200 100" className="viz-svg">
      <rect x="20" y="70" width="60" height="25" rx="4" fill="#DBEAFE" stroke="#60A5FA" strokeWidth="2" />
      <rect x="120" y="70" width="60" height="25" rx="4" fill="#FEE2E2" stroke="#F87171" strokeWidth="2" />
      <text x="50" y="87" textAnchor="middle" fill="#1D4ED8" fontSize="8" fontWeight="500">Not Spam</text>
      <text x="150" y="87" textAnchor="middle" fill="#DC2626" fontSize="8" fontWeight="500">Spam</text>
      {blueDots.map((dot, i) => (
        <circle
          key={`b${i}`}
          r="6"
          fill="#3B82F6"
          cx={isPlaying ? dot.endX : dot.startX}
          cy={isPlaying ? dot.endY : dot.startY}
          style={{ transition: `all 0.8s ease-out ${i * 0.15}s` }}
        />
      ))}
      {redDots.map((dot, i) => (
        <circle
          key={`r${i}`}
          r="6"
          fill="#EF4444"
          cx={isPlaying ? dot.endX : dot.startX}
          cy={isPlaying ? dot.endY : dot.startY}
          style={{ transition: `all 0.8s ease-out ${(i + 4) * 0.15}s` }}
        />
      ))}
    </svg>
  );
}

function RegressionViz({ isPlaying }: { isPlaying: boolean }) {
  const points = [
    { x: 25, y: 72 }, { x: 45, y: 62 }, { x: 60, y: 55 }, { x: 80, y: 48 },
    { x: 100, y: 42 }, { x: 120, y: 35 }, { x: 140, y: 30 }, { x: 160, y: 24 }, { x: 180, y: 18 },
  ];

  return (
    <svg viewBox="0 0 200 100" className="viz-svg">
      <line x1="15" y1="85" x2="190" y2="85" stroke="#CBD5E1" strokeWidth="1" />
      <line x1="15" y1="85" x2="15" y2="10" stroke="#CBD5E1" strokeWidth="1" />
      <text x="100" y="98" textAnchor="middle" fill="#64748B" fontSize="7">House Size</text>
      {points.map((p, i) => <circle key={i} cx={p.x} cy={p.y} r="4" fill="#818CF8" />)}
      <line
        x1="20" y1="75" x2="185" y2="15"
        stroke="#6366F1" strokeWidth="2"
        strokeDasharray="200"
        strokeDashoffset={isPlaying ? 0 : 200}
        style={{ transition: 'stroke-dashoffset 1.5s ease-out' }}
      />
    </svg>
  );
}

function ClusteringViz({ isPlaying }: { isPlaying: boolean }) {
  const clusters = [
    { startX: 60, startY: 50, endX: 35, endY: 28, color: '#10B981' },
    { startX: 100, startY: 30, endX: 45, endY: 33, color: '#10B981' },
    { startX: 140, startY: 60, endX: 40, endY: 38, color: '#10B981' },
    { startX: 50, startY: 40, endX: 155, endY: 28, color: '#8B5CF6' },
    { startX: 120, startY: 20, endX: 165, endY: 33, color: '#8B5CF6' },
    { startX: 170, startY: 50, endX: 160, endY: 38, color: '#8B5CF6' },
    { startX: 30, startY: 25, endX: 90, endY: 72, color: '#F97316' },
    { startX: 160, startY: 35, endX: 100, endY: 77, color: '#F97316' },
    { startX: 110, startY: 55, endX: 95, endY: 82, color: '#F97316' },
  ];

  return (
    <svg viewBox="0 0 200 100" className="viz-svg">
      <text x="38" y="15" textAnchor="middle" fill="#059669" fontSize="7" fontWeight="500"
        style={{ opacity: isPlaying ? 1 : 0, transition: 'opacity 0.5s ease-out 1s' }}>Group A</text>
      <text x="160" y="15" textAnchor="middle" fill="#7C3AED" fontSize="7" fontWeight="500"
        style={{ opacity: isPlaying ? 1 : 0, transition: 'opacity 0.5s ease-out 1s' }}>Group B</text>
      <text x="95" y="98" textAnchor="middle" fill="#EA580C" fontSize="7" fontWeight="500"
        style={{ opacity: isPlaying ? 1 : 0, transition: 'opacity 0.5s ease-out 1s' }}>Group C</text>
      {clusters.map((dot, i) => (
        <circle
          key={i}
          r="6"
          fill={isPlaying ? dot.color : '#94A3B8'}
          cx={isPlaying ? dot.endX : dot.startX}
          cy={isPlaying ? dot.endY : dot.startY}
          style={{ transition: `all 1s ease-out ${i * 0.08}s` }}
        />
      ))}
    </svg>
  );
}

function ReinforcementViz({ isPlaying }: { isPlaying: boolean }) {
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (isPlaying) {
      setAttempt(0);
      const t1 = setTimeout(() => setAttempt(1), 600);
      const t2 = setTimeout(() => setAttempt(2), 1200);
      const t3 = setTimeout(() => setAttempt(3), 1800);
      return () => { clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); };
    } else {
      setAttempt(0);
    }
  }, [isPlaying]);

  const positions = [
    { x: 25, y: 72 },
    { x: 65, y: 90 },
    { x: 115, y: 90 },
    { x: 175, y: 27 },
  ];
  const pos = positions[attempt];
  const failed = attempt === 1 || attempt === 2;
  const success = attempt === 3;

  return (
    <svg viewBox="0 0 200 100" className="viz-svg">
      <rect x="10" y="80" width="40" height="8" rx="2" fill="#CBD5E1" />
      <rect x="60" y="65" width="35" height="8" rx="2" fill="#CBD5E1" />
      <rect x="105" y="50" width="35" height="8" rx="2" fill="#CBD5E1" />
      <rect x="150" y="35" width="40" height="8" rx="2" fill="#CBD5E1" />
      <line x1="180" y1="15" x2="180" y2="35" stroke="#94A3B8" strokeWidth="2" />
      <polygon points="180,15 195,22 180,29" fill="#22C55E" />
      <circle
        cx={pos.x} cy={pos.y} r="8"
        fill={success ? '#22C55E' : failed ? '#F87171' : '#3B82F6'}
        style={{ transition: 'all 0.5s ease-out' }}
      />
      <text x="100" y="98" textAnchor="middle" fill={success ? '#16A34A' : failed ? '#DC2626' : '#64748B'} fontSize="8">
        {!isPlaying ? 'Click Play' : success ? 'Learned the path!' : failed ? 'Trying again...' : 'Learning...'}
      </text>
    </svg>
  );
}

export default function App() {
  const [playing, setPlaying] = useState<Record<AlgorithmType, boolean>>({
    classification: false, regression: false, clustering: false, reinforcement: false,
  });
  const [mode, setMode] = useState<'explore' | 'quiz'>('explore');
  const [quizIndex, setQuizIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [feedback, setFeedback] = useState<string | null>(null);

  const algorithms: { type: AlgorithmType; title: string; desc: string }[] = [
    { type: 'classification', title: 'Classification', desc: 'Sorting into categories' },
    { type: 'regression', title: 'Regression', desc: 'Predicting numbers' },
    { type: 'clustering', title: 'Clustering', desc: 'Finding natural groups' },
    { type: 'reinforcement', title: 'Reinforcement', desc: 'Learning by trial & error' },
  ];

  const toggle = (t: AlgorithmType) => setPlaying(p => ({ ...p, [t]: !p[t] }));
  const playAll = () => setPlaying({ classification: true, regression: true, clustering: true, reinforcement: true });
  const resetAll = () => setPlaying({ classification: false, regression: false, clustering: false, reinforcement: false });

  const handleQuizAnswer = (answer: AlgorithmType) => {
    const correct = quizQuestions[quizIndex].answer === answer;
    if (correct) {
      setScore(s => s + 1);
      setFeedback('Correct!');
    } else {
      setFeedback(`Not quite. ${quizQuestions[quizIndex].hint}`);
    }
    setTimeout(() => {
      setFeedback(null);
      if (quizIndex < quizQuestions.length - 1) {
        setQuizIndex(i => i + 1);
      } else {
        setMode('explore');
        alert(`Quiz complete! Score: ${correct ? score + 1 : score}/${quizQuestions.length}`);
        setQuizIndex(0);
        setScore(0);
      }
    }, 1500);
  };

  const renderViz = (t: AlgorithmType, isPlaying: boolean) => {
    switch (t) {
      case 'classification': return <ClassificationViz isPlaying={isPlaying} />;
      case 'regression': return <RegressionViz isPlaying={isPlaying} />;
      case 'clustering': return <ClusteringViz isPlaying={isPlaying} />;
      case 'reinforcement': return <ReinforcementViz isPlaying={isPlaying} />;
    }
  };

  return (
    <div className="app">
      <h1>Algorithm Type Explorer</h1>
      <p className="intro">Watch each algorithm type in action, then test your understanding.</p>

      <div className="mode-toggle">
        <button className={mode === 'explore' ? 'active' : ''} onClick={() => setMode('explore')}>Explore</button>
        <button className={mode === 'quiz' ? 'active' : ''} onClick={() => { setMode('quiz'); setQuizIndex(0); setScore(0); }}>Quiz Me</button>
      </div>

      {mode === 'explore' ? (
        <>
          <div className="controls">
            <button onClick={playAll} className="primary">Play All</button>
            <button onClick={resetAll}>Reset</button>
          </div>
          <div className="grid">
            {algorithms.map(algo => (
              <div key={algo.type} className="card" onClick={() => toggle(algo.type)}>
                <h3>{algo.title}</h3>
                <p className="desc">{algo.desc}</p>
                {renderViz(algo.type, playing[algo.type])}
                <span className="click-hint">Click to {playing[algo.type] ? 'reset' : 'play'}</span>
              </div>
            ))}
          </div>
        </>
      ) : (
        <div className="quiz">
          <div className="quiz-progress">Question {quizIndex + 1} of {quizQuestions.length}</div>
          <div className="quiz-question">
            <p>{quizQuestions[quizIndex].description}</p>
            {feedback && <div className={`feedback ${feedback === 'Correct!' ? 'correct' : 'incorrect'}`}>{feedback}</div>}
          </div>
          <div className="quiz-options">
            {algorithms.map(algo => (
              <button key={algo.type} onClick={() => handleQuizAnswer(algo.type)} disabled={!!feedback}>
                {algo.title}
              </button>
            ))}
          </div>
          <div className="score">Score: {score}</div>
        </div>
      )}

      <div className="reflection">
        <h3>Reflection</h3>
        <ul>
          <li>Which algorithm would predict tomorrow's temperature?</li>
          <li>If you wanted to discover user groups without defining them first, which would you use?</li>
          <li>Why might reinforcement learning be overkill for spam detection?</li>
        </ul>
      </div>
    </div>
  );
}

