.mode-toggle button.active { background: #6366f1; color: white; border-color: #6366f1; }
.controls { display: flex; gap: 8px; margin-bottom: 1rem; }
.controls button { padding: 8px 16px; border: 1px solid #e2e8f0; background: white; border-radius: 6px; cursor: pointer; font-size: 0.875rem; }
.controls button.primary { background: #6366f1; color: white; border-color: #6366f1; }
