.card { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; cursor: pointer; transition: border-color 0.2s; }
.card:hover { border-color: #a5b4fc; }
.card h3 { font-size: 1rem; color: #334155; margin: 0 0 4px 0; }
.card .desc { font-size: 0.75rem; color: #64748b; margin: 0 0 12px 0; }
.viz-svg { width: 100%; height: 120px; }
.click-hint { display: block; text-align: center; font-size: 0.625rem; color: #94a3b8; margin-top: 8px; }
.quiz { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 24px; }
.quiz-progress { font-size: 0.75rem; color: #64748b; margin-bottom: 16px; }
