.feedback { padding: 8px 12px; border-radius: 6px; font-size: 0.875rem; }
.feedback.correct { background: #dcfce7; color: #166534; }
.feedback.incorrect { background: #fef3c7; color: #92400e; }
.quiz-options { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-bottom: 16px; }
.quiz-options button { padding: 12px; border: 1px solid #e2e8f0; background: white; border-radius: 8px; cursor: pointer; font-size: 0.875rem; transition: all 0.2s; }
.quiz-options button:hover:not(:disabled) { border-color: #6366f1; background: #f5f3ff; }
.quiz-options button:disabled { opacity: 0.6; cursor: not-allowed; }
.score { font-size: 0.875rem; color: #64748b; }
.reflection { margin-top: 24px; padding: 16px; background: #f1f5f9; border-radius: 8px; }
.reflection h3 { font-size: 0.875rem; color: #334155; margin: 0 0 8px 0; }
.reflection ul { margin: 0; padding-left: 20px; }
.reflection li { font-size: 0.875rem; color: #64748b; margin-bottom: 4px; }
